using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
namespace WinterDesk {
internal sealed class LivingSnowman:IDisposable {
 internal Layer Window=new Layer(),Construction=new Layer();internal Sprite BuildImage;internal LivingSnowman Leader,Partner;internal int BuildFrame=-1;internal SnowmanMotion Motion;internal int Frame=-1;internal bool Held;internal double GrabX,GrabY;
 public void Dispose(){Window.Dispose();Construction.Dispose();if(BuildImage!=null)BuildImage.Dispose();}
}
internal sealed partial class Controller {
 internal const int MaxSnowmen=24;readonly List<LivingSnowman> snowmen=new List<LivingSnowman>();readonly SpriteCache<string> snowmanFrames=new SpriteCache<string>(96,25165824);double lastSnowmanSpawn,lastPenguinSpawn,teamAt;
 Sprite SnowmanImage(int pose,float scale,int scarf=0,int direction=1){int bucket=Math.Max(12,(int)Math.Round(scale*20)*5);string key=bucket+"/"+(scarf%6)+"/"+direction+"/"+DrawnArt.SnowmanIdentity(pose);Sprite image;if(!snowmanFrames.TryGetValue(key,out image)){using(var b=DrawnArt.Snowman(pose,bucket/100f,scarf,direction))image=new Sprite(b);snowmanFrames.Add(key,image);}return image;}
 internal void SpawnSnowman(){Native.POINT cursor;Native.GetCursorPos(out cursor);float scale=.598f*Scale(ScreenAt(cursor.X,cursor.Y));SpawnSnowmanAt(cursor.X,cursor.Y+100*scale,scale,true);}
 System.Windows.Forms.Screen ScreenAt(double x,double y){return System.Windows.Forms.Screen.FromPoint(new Point((int)x,(int)y));}
 bool CanSpawnSnowman(bool builder){return snowmen.Count<MaxSnowmen;}
 LivingSnowman SpawnSnowmanAt(double x,double y,float scale,bool builder){if(!CanSpawnSnowman(builder))return null;var actor=new LivingSnowman{Motion=new SnowmanMotion(x,y,scale,builder,random.Next(2)==0?-1:1)};actor.Motion.SizeLimit=3.2f*Scale(ScreenAt(x,y));actor.Window.SetInput(true);actor.Window.Hit=delegate(int xx,int yy){var image=SnowmanImage(actor.Motion.Pose,actor.Motion.Scale,actor.Motion.Scarf,actor.Motion.Direction);return xx>image.Width*.15&&xx<image.Width*.88&&yy>image.Height*.05&&yy<image.Height*.97;};
  actor.Motion.EscapeAt=5+random.NextDouble()*2;actor.Window.MouseDown=delegate(int xx,int yy){BreakTeam(actor);actor.Held=true;actor.Motion.Grab();actor.GrabX=actor.Window.X+xx-actor.Motion.X;actor.GrabY=actor.Window.Y+yy-actor.Motion.Y;};actor.Window.MouseDrag=delegate(int xx,int yy){actor.Motion.X=actor.Window.X+xx-actor.GrabX;actor.Motion.Y=actor.Window.Y+yy-actor.Motion.Y;};actor.Window.MouseUp=delegate(int xx,int yy){actor.Held=false;actor.Motion.Drop(ledges);};snowmen.Add(actor);return actor;
 }
 void BreakTeam(LivingSnowman actor){var leader=actor.Leader??actor;var partner=leader.Partner;if(partner==null)return;leader.Partner=null;partner.Leader=null;foreach(var member in new[]{leader,partner}){var m=member.Motion;m.ChildMultiplier=.5;m.PlacedBalls=0;if(m.State!=SnowmanState.Done){m.State=SnowmanState.Waiting;m.Age=0;m.EscapeAt=m.Time+1;}}}
 void FindTeams(double now){if(now<teamAt)return;teamAt=now+.4;for(int i=0;i<snowmen.Count;i++){var a=snowmen[i];if(a.Held||a.Leader!=null||a.Partner!=null||!a.Motion.CanTeam)continue;for(int j=i+1;j<snowmen.Count;j++){var b=snowmen[j];if(b.Held||b.Leader!=null||b.Partner!=null||!SnowmanMotion.CanJoin(a.Motion,b.Motion))continue;var ledge=ledges.Find(l=>l.Handle==a.Motion.Support);if(ledge!=null&&ledge.Bounds.Width<450*a.Motion.Scale)continue;a.Partner=b;b.Leader=a;a.Motion.ChildMultiplier=2;a.Motion.EscapeAt=Math.Min(a.Motion.EscapeAt,a.Motion.Time+.6);break;}}}
 void AnimateSnowmen(double dt,double now){FindTeams(now);var newborns=new List<LivingSnowman>();for(int i=snowmen.Count-1;i>=0;i--){var actor=snowmen[i];var m=actor.Motion;var screen=ScreenAt(m.X,m.Y);bool hidden=screens.Exists(r=>r.Screen.DeviceName==screen.DeviceName&&r.FullScreen);if(hidden){actor.Window.Show(false);actor.Construction.Show(false);continue;}
   if(actor.Held){m.Time+=dt;Native.POINT cursor;Native.GetCursorPos(out cursor);m.X=cursor.X-actor.GrabX;m.Y=cursor.Y-actor.GrabY;if((Native.GetAsyncKeyState(1)&0x8000)==0){actor.Held=false;m.Drop(ledges);}}
   else if(actor.Leader!=null){var lead=actor.Leader;var lm=lead.Motion;if(lead.Held||lm.State==SnowmanState.Done||lm.State==SnowmanState.Falling){BreakTeam(actor);m.Drop(ledges);}else{m.Time+=dt;m.Age=lm.Age;m.State=lm.State;m.X+=(lm.X+lm.BuildDirection*150*m.Scale-m.X)*(1-Math.Exp(-dt*8));m.Y=lm.Y;m.Support=lm.Support;m.SupportOffset=m.X-(ledges.Find(l=>l.Handle==m.Support)??new Ledge()).Bounds.Left;m.Direction=-lm.BuildDirection;m.PlacedBalls=0;var support=ledges.Find(l=>l.Handle==m.Support);if(support!=null&&!support.Supports(m.X)){BreakTeam(actor);m.Drop(ledges);}}}
   else {m.Tick(dt,FloorAt(m.X,m.Y),screen.WorkingArea.Left,screen.WorkingArea.Right,ledges);}
   if(m.State==SnowmanState.Done){BreakTeam(actor);actor.Dispose();snowmen.RemoveAt(i);continue;}if(m.ChildPending){m.ChildPending=false;newborns.Add(actor);}int pose=actor.Held?100+(int)(m.Time*36)%64:m.Pose;var image=SnowmanImage(pose,m.Scale,m.Scarf,m.Direction);int x=(int)(m.X-image.Width*.5),y=(int)(m.Y-image.Height+3*m.Scale);int frameKey=pose+(m.Direction<0?512:0);if(frameKey!=actor.Frame){actor.Window.Paint(image,x,y);actor.Frame=frameKey;}else actor.Window.Move(x,y);var cuts=new List<Rectangle>();if(m.Support!=IntPtr.Zero){var support=ledges.Find(l=>l.Handle==m.Support);if(support!=null)cuts=support.Blockers;}actor.Window.Clip(new Rectangle(x,y,image.Width,image.Height),cuts);actor.Window.Show(true);DrawConstruction(actor);
  }foreach(var parentActor in newborns){var parent=parentActor.Motion;if(parent.Generation<1&&snowmen.Count<MaxSnowmen){var created=SpawnSnowmanAt(parent.TargetX+parent.BuildDirection*(47*parent.ChildScale+75*parent.Scale),parent.Y,parent.ChildScale,false);if(created!=null){var child=created.Motion;child.Generation=Math.Max(parent.Generation,parentActor.Partner==null?0:parentActor.Partner.Motion.Generation)+1;if(child.Generation>=1)child.EscapeAt=0;child.Scarf=SnowFamily.NextScarf(parent.Scarf,random.Next(5),parentActor.Partner==null?-1:parentActor.Partner.Motion.Scarf);child.Drop(ledges);if(child.Support!=IntPtr.Zero||Math.Abs(child.Y-FloorAt(child.X,child.Y))<8*child.Scale)child.State=SnowmanState.Awakening;child.Age=0;}}if(parentActor.Partner!=null){var partner=parentActor.Partner;parentActor.Partner=null;partner.Leader=null;partner.Motion.ChildrenBuilt=1;partner.Motion.PlacedBalls=0;partner.Motion.Direction=partner.Motion.ExitDirection;partner.Motion.State=SnowmanState.Leaving;partner.Motion.Age=0;}}
 }
 void ClearSnowmen(){foreach(var a in snowmen)a.Dispose();snowmen.Clear();snowmanFrames.Clear();}
 internal int LivingSnowmanCount {get{return snowmen.Count;}}
 void AwakenStack(SnowBall head){if(!CanSpawnSnowman(true))return;var middle=head.Parent;var root=middle==null?null:middle.Parent;if(root==null||root.Parent!=null)return;float scale=(float)Math.Max(.32,Math.Min(2.5,(head.Radius+middle.Radius+root.Radius)*2/185));double x=root.X,y=root.Y+root.Radius;var created=SpawnSnowmanAt(x,y,scale,true);if(created==null)return;created.Motion.AdoptStackBase(x,y,FloorAt(x,y),ledges);var remove=new[]{head,middle,root};foreach(var b in remove){snowBalls.Remove(b);b.Dispose();}}
 void DrawConstruction(LivingSnowman actor){var m=actor.Motion;if(actor.Leader!=null||m.BuildStage<0){actor.Construction.Show(false);return;}int frame=(int)(m.Time*30);var bounds=SnowConstruction.Bounds(m);if(actor.BuildFrame!=frame){using(var b=SnowConstruction.Render(m,bounds)){if(actor.BuildImage==null||actor.BuildImage.Width!=b.Width||actor.BuildImage.Height!=b.Height){if(actor.BuildImage!=null)actor.BuildImage.Dispose();actor.BuildImage=new Sprite(b);}else actor.BuildImage.Upload(b);actor.Construction.Paint(actor.BuildImage,bounds.X,bounds.Y);actor.BuildFrame=frame;}}else actor.Construction.Move(bounds.X,bounds.Y);var blockers=new List<Rectangle>();if(m.Support!=IntPtr.Zero){var ledge=ledges.Find(l=>l.Handle==m.Support);if(ledge!=null)blockers=ledge.Blockers;}actor.Construction.Clip(bounds,blockers);actor.Construction.Show(true);}
}
}
